--
-- Name: _partial_view_3; Type: VIEW; Schema: _timescaledb_internal; Owner: fa
--

CREATE VIEW _timescaledb_internal._partial_view_3 AS
 SELECT kpi_code,
    geo,
    source_code,
    public.time_bucket('1 year'::interval, period) AS year,
    avg(value) AS avg_value,
    min(value) AS min_value,
    max(value) AS max_value,
    count(*) AS n
   FROM public.kpi_observation
  GROUP BY kpi_code, geo, source_code, (public.time_bucket('1 year'::interval, period));


ALTER VIEW _timescaledb_internal._partial_view_3 OWNER TO fa;

