-- Name: COLUMN dim_geo.policy_rate_proxy_geo; Type: COMMENT; Schema: ssot; Owner: fa
--

COMMENT ON COLUMN ssot.dim_geo.policy_rate_proxy_geo IS 'Geo whose policy rate stands in (ARE -> USA under the peg). Resolved at view time, never stored as a row.';


--
-- Name: country360_wide; Type: VIEW; Schema: ssot; Owner: fa
--

CREATE VIEW ssot.country360_wide AS
 WITH own AS (
         SELECT country360.geo_code,
            country360.frequency,
            country360.period_start,
            country360.kpi_code,
            country360.value,
            country360.status,
            country360.data_label,
            false AS is_proxy,
            NULL::text AS proxy_geo
           FROM ssot.country360
          WHERE ((country360.axis_code = '_T'::text) AND (country360.member_code = '_T'::text) AND (country360.basis = 'OUTTURN'::text))
        ), proxied AS (
         SELECT g.geo_code,
            c.frequency,
            c.period_start,
            c.kpi_code,
            c.value,
            c.status,
            c.data_label,
            true AS "?column?",
            g.policy_rate_proxy_geo
           FROM (ssot.dim_geo g
             JOIN ssot.country360 c ON (((c.geo_code = g.policy_rate_proxy_geo) AND (c.kpi_code = 'POLICY_RATE'::text) AND (c.axis_code = '_T'::text) AND (c.member_code = '_T'::text) AND (c.basis = 'OUTTURN'::text))))
          WHERE ((g.policy_rate_proxy_geo IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
                   FROM ssot.country360 o
                  WHERE ((o.geo_code = g.geo_code) AND (o.kpi_code = 'POLICY_RATE'::text) AND (o.frequency = c.frequency) AND (o.period_start = c.period_start) AND (o.axis_code = '_T'::text) AND (o.member_code = '_T'::text) AND (o.basis = 'OUTTURN'::text))))))
        ), u AS (
         SELECT own.geo_code,
            own.frequency,
            own.period_start,
            own.kpi_code,
            own.value,
            own.status,
            own.data_label,
            own.is_proxy,
            own.proxy_geo
           FROM own
        UNION ALL
         SELECT proxied.geo_code,
            proxied.frequency,
            proxied.period_start,
            proxied.kpi_code,
            proxied.value,
            proxied.status,
            proxied.data_label,
            proxied."?column?",
            proxied.policy_rate_proxy_geo
           FROM proxied
        )
 SELECT geo_code,
    frequency,
    period_start,
    (EXTRACT(year FROM period_start))::integer AS year,
    (EXTRACT(month FROM period_start))::integer AS month,
    max(value) FILTER (WHERE (kpi_code = 'GDP_REAL_GROWTH'::text)) AS gdp_real_growth,
    max(value) FILTER (WHERE (kpi_code = 'GDP_NOMINAL_USD'::text)) AS gdp_nominal_usd,
    max(value) FILTER (WHERE (kpi_code = 'GDP_PER_CAPITA_USD'::text)) AS gdp_per_capita_usd,
    max(value) FILTER (WHERE (kpi_code = 'GDP_CONSTANT_2015_USD'::text)) AS gdp_constant_2015_usd,
    max(value) FILTER (WHERE (kpi_code = 'CPI_YOY'::text)) AS cpi_yoy,
    max(value) FILTER (WHERE (kpi_code = 'UNEMPLOYMENT_RATE'::text)) AS unemployment_rate,
    max(value) FILTER (WHERE (kpi_code = 'POPULATION'::text)) AS population,
    max(value) FILTER (WHERE (kpi_code = 'CURRENT_ACCOUNT_PCT_GDP'::text)) AS current_account_pct_gdp,
    max(value) FILTER (WHERE (kpi_code = 'FISCAL_BALANCE_PCT_GDP'::text)) AS fiscal_balance_pct_gdp,
    max(value) FILTER (WHERE (kpi_code = 'GOV_DEBT_PCT_GDP'::text)) AS gov_debt_pct_gdp,
    max(value) FILTER (WHERE (kpi_code = 'GOV_REVENUE_PCT_GDP'::text)) AS gov_revenue_pct_gdp,
    max(value) FILTER (WHERE (kpi_code = 'GOV_EXPENDITURE_PCT_GDP'::text)) AS gov_expenditure_pct_gdp,
    max(value) FILTER (WHERE (kpi_code = 'EXPORTS_PCT_GDP'::text)) AS exports_pct_gdp,
    max(value) FILTER (WHERE (kpi_code = 'FDI_INFLOW_USD'::text)) AS fdi_inflow_usd,
    max(value) FILTER (WHERE (kpi_code = 'AGRI_VALUE_ADDED_USD'::text)) AS agri_value_added_usd,
    max(value) FILTER (WHERE (kpi_code = 'POLICY_RATE'::text)) AS policy_rate,
    bool_or(is_proxy) FILTER (WHERE (kpi_code = 'POLICY_RATE'::text)) AS policy_rate_is_proxy,
    max(proxy_geo) FILTER (WHERE (kpi_code = 'POLICY_RATE'::text)) AS policy_rate_proxy_geo,
    max(value) FILTER (WHERE (kpi_code = 'BOND_YIELD_10Y'::text)) AS bond_yield_10y,
    max(value) FILTER (WHERE (kpi_code = 'FX_USD_INDEX'::text)) AS fx_usd_index,
    max(value) FILTER (WHERE (kpi_code = 'FX_EUR_USD'::text)) AS fx_eur_usd,
    max(value) FILTER (WHERE ((kpi_code = 'OIL_BRENT'::text) AND (status <> 'PROJECTION'::text))) AS oil_brent_spot,
    max(value) FILTER (WHERE ((kpi_code = 'OIL_BRENT'::text) AND (status = 'PROJECTION'::text))) AS oil_brent_forecast,
    max(value) FILTER (WHERE ((kpi_code = 'OIL_WTI'::text) AND (status <> 'PROJECTION'::text))) AS oil_wti_spot,
    max(value) FILTER (WHERE ((kpi_code = 'OIL_WTI'::text) AND (status = 'PROJECTION'::text))) AS oil_wti_forecast,
    max(value) FILTER (WHERE (kpi_code = 'PARTNER_DEMAND'::text)) AS partner_demand,
    max(value) FILTER (WHERE (kpi_code = 'NON_OIL_GDP_GROWTH'::text)) AS non_oil_gdp_growth,
    max(value) FILTER (WHERE (kpi_code = 'PMI'::text)) AS pmi,
    max(status) FILTER (WHERE (kpi_code = 'GDP_REAL_GROWTH'::text)) AS gdp_real_growth_status,
        CASE
            WHEN bool_or((data_label = 'sample'::text)) THEN 'sample'::text
            WHEN bool_or((data_label = 'indicative'::text)) THEN 'indicative'::text
            ELSE 'real'::text
        END AS data_label_worst,
    (count(*))::integer AS n_kpis
   FROM u
  GROUP BY geo_code, frequency, period_start;


ALTER VIEW ssot.country360_wide OWNER TO fa;

--
-- Name: compat_gold_imf_weo; Type: VIEW; Schema: ssot; Owner: fa
--

CREATE VIEW ssot.compat_gold_imf_weo AS
 SELECT w.geo_code AS country_code,
    w.period_start AS period,
    w.year,
    w.month,
    g.economy_group,
    w.cpi_yoy,
    w.current_account_pct_gdp,
    w.fiscal_balance_pct_gdp,
    w.gdp_nominal_usd,
    w.gdp_per_capita_usd,
    w.gdp_real_growth,
    w.gov_debt_pct_gdp,
    w.population,
    w.unemployment_rate
   FROM (ssot.country360_wide w
     JOIN ssot.dim_geo g USING (geo_code))
  WHERE ((w.frequency = 'A'::bpchar) AND (EXISTS ( SELECT 1
           FROM ssot.country360 c
          WHERE ((c.geo_code = w.geo_code) AND (c.period_start = w.period_start) AND (c.frequency = 'A'::bpchar) AND (c.source_code = 'IMF_WEO'::text)))));


ALTER VIEW ssot.compat_gold_imf_weo OWNER TO fa;

--
-- Name: dim_kpi; Type: TABLE; Schema: ssot; Owner: fa
--

CREATE TABLE ssot.dim_kpi (
    kpi_code text NOT NULL,
    name_en text NOT NULL,
    name_ar text,
    category text NOT NULL,
    unit text NOT NULL,
    frequency_canonical character(1) NOT NULL,
    aggregation text DEFAULT 'AVG'::text NOT NULL,
    direction text DEFAULT 'NEUTRAL'::text NOT NULL,
    plausibility_min double precision,
    plausibility_max double precision,
    decimals smallint DEFAULT 2 NOT NULL,
    is_derived boolean DEFAULT false NOT NULL,
    description text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dim_kpi_aggregation_check CHECK ((aggregation = ANY (ARRAY['AVG'::text, 'SUM'::text, 'EOP'::text, 'LAST'::text]))),
    CONSTRAINT dim_kpi_category_check CHECK ((category = ANY (ARRAY['MACRO'::text, 'PRICES'::text, 'RATES'::text, 'FX'::text, 'COMMODITY'::text, 'FISCAL'::text, 'ACTIVITY'::text, 'DEMOGRAPHIC'::text]))),
    CONSTRAINT dim_kpi_check CHECK (((plausibility_min IS NULL) OR (plausibility_max IS NULL) OR (plausibility_min < plausibility_max))),
    CONSTRAINT dim_kpi_code_shape CHECK ((kpi_code ~ '^[A-Z0-9_]{2,40}$'::text)),
    CONSTRAINT dim_kpi_direction_check CHECK ((direction = ANY (ARRAY['HIGHER_BETTER'::text, 'LOWER_BETTER'::text, 'NEUTRAL'::text]))),
    CONSTRAINT dim_kpi_frequency_canonical_check CHECK ((frequency_canonical = ANY (ARRAY['A'::bpchar, 'Q'::bpchar, 'M'::bpchar, 'D'::bpchar])))
);


ALTER TABLE ssot.dim_kpi OWNER TO fa;

--
-- Name: country360_annual; Type: VIEW; Schema: ssot; Owner: fa
--

CREATE VIEW ssot.country360_annual AS
 SELECT country360.geo_code,
    country360.kpi_code,
    'A'::character(1) AS frequency,
    country360.period_start,
    country360.value,
    country360.unit,
    country360.status,
    country360.data_label,
    country360.source_code,
    country360.vintage_id,
    false AS is_rollup,
    1 AS n_obs
   FROM ssot.country360
  WHERE ((country360.frequency = 'A'::bpchar) AND (country360.axis_code = '_T'::text) AND (country360.member_code = '_T'::text) AND (country360.basis = 'OUTTURN'::text))
UNION ALL
 SELECT c.geo_code,
    c.kpi_code,
    'A'::bpchar AS frequency,
    (date_trunc('year'::text, (c.period_start)::timestamp with time zone))::date AS period_start,
        CASE k.aggregation
            WHEN 'SUM'::text THEN sum(c.value)
            WHEN 'AVG'::text THEN avg(c.value)
            ELSE (array_agg(c.value ORDER BY c.period_start DESC))[1]
        END AS value,
    max(c.unit) AS unit,
        CASE
            WHEN bool_or((c.status = 'PROJECTION'::text)) THEN 'PROJECTION'::text
            ELSE 'ACTUAL'::text
        END AS status,
        CASE
            WHEN bool_or((c.data_label = 'sample'::text)) THEN 'sample'::text
            WHEN bool_or((c.data_label = 'indicative'::text)) THEN 'indicative'::text
            ELSE 'real'::text
        END AS data_label,
    max(c.source_code) AS source_code,
    max(c.vintage_id) AS vintage_id,
    true AS is_rollup,
    (count(*))::integer AS n_obs
   FROM (ssot.country360 c
     JOIN ssot.dim_kpi k USING (kpi_code))
  WHERE ((c.frequency = ANY (ARRAY['Q'::bpchar, 'M'::bpchar, 'D'::bpchar])) AND (c.axis_code = '_T'::text) AND (c.member_code = '_T'::text) AND (c.basis = 'OUTTURN'::text) AND (NOT (EXISTS ( SELECT 1
           FROM ssot.country360 a
          WHERE ((a.geo_code = c.geo_code) AND (a.kpi_code = c.kpi_code) AND (a.frequency = 'A'::bpchar) AND (a.period_start = (date_trunc('year'::text, (c.period_start)::timestamp with time zone))::date) AND (a.axis_code = '_T'::text) AND (a.member_code = '_T'::text) AND (a.basis = 'OUTTURN'::text))))))
  GROUP BY c.geo_code, c.kpi_code, k.aggregation, (date_trunc('year'::text, (c.period_start)::timestamp with time zone));


ALTER VIEW ssot.country360_annual OWNER TO fa;

--
-- Name: country360_latest; Type: VIEW; Schema: ssot; Owner: fa
--

CREATE VIEW ssot.country360_latest AS
 SELECT DISTINCT ON (geo_code, kpi_code, frequency) geo_code,
    kpi_code,
    frequency,
    period_start,
    period_end,
    value,
    unit,
    status,
    source_code,
    vintage_id,
    vintage_date,
    data_label,
    confidence,
    quality_flags,
    obs_id
   FROM ssot.country360
  WHERE ((axis_code = '_T'::text) AND (member_code = '_T'::text) AND (basis = 'OUTTURN'::text) AND (status = ANY (ARRAY['ACTUAL'::text, 'ESTIMATE'::text, 'PRELIMINARY'::text])))
  ORDER BY geo_code, kpi_code, frequency, period_start DESC;


ALTER VIEW ssot.country360_latest OWNER TO fa;

--
-- Name: country360_monthly; Type: VIEW; Schema: ssot; Owner: fa
--

CREATE VIEW ssot.country360_monthly AS
 SELECT country360.geo_code,
    country360.kpi_code,
    'M'::character(1) AS frequency,
    country360.period_start,
    country360.value,
    country360.unit,
    country360.status,
    country360.data_label,
    country360.source_code,
    country360.vintage_id,
    false AS is_rollup,
    1 AS n_obs
   FROM ssot.country360
  WHERE ((country360.frequency = 'M'::bpchar) AND (country360.axis_code = '_T'::text) AND (country360.member_code = '_T'::text) AND (country360.basis = 'OUTTURN'::text))
UNION ALL
 SELECT c.geo_code,
    c.kpi_code,
    'M'::bpchar AS frequency,
    (date_trunc('month'::text, (c.period_start)::timestamp with time zone))::date AS period_start,
        CASE k.aggregation
            WHEN 'SUM'::text THEN sum(c.value)
            WHEN 'AVG'::text THEN avg(c.value)
            ELSE (array_agg(c.value ORDER BY c.period_start DESC))[1]
        END AS value,
    max(c.unit) AS unit,
        CASE
            WHEN bool_or((c.status = 'PROJECTION'::text)) THEN 'PROJECTION'::text
            ELSE 'ACTUAL'::text
        END AS status,
        CASE
            WHEN bool_or((c.data_label = 'sample'::text)) THEN 'sample'::text
            WHEN bool_or((c.data_label = 'indicative'::text)) THEN 'indicative'::text
            ELSE 'real'::text
        END AS data_label,
    max(c.source_code) AS source_code,
    max(c.vintage_id) AS vintage_id,
    true AS is_rollup,
    (count(*))::integer AS n_obs
   FROM (ssot.country360 c
     JOIN ssot.dim_kpi k USING (kpi_code))
  WHERE ((c.frequency = 'D'::bpchar) AND (c.axis_code = '_T'::text) AND (c.member_code = '_T'::text) AND (c.basis = 'OUTTURN'::text))
  GROUP BY c.geo_code, c.kpi_code, k.aggregation, (date_trunc('month'::text, (c.period_start)::timestamp with time zone));


ALTER VIEW ssot.country360_monthly OWNER TO fa;

